const page = dv.current()
delete page.file
dv.list(Object.keys(page))

let pages = dv.pages();
let fields = new Set();
for (let page of pages) {
    for (let key of Object.keys(page)) {
        if (key !== "file") fields.add(key);
    }
}
dv.list(Array.from(fields).sort());
